import unittest
from src.calc import total

class Checks(unittest.TestCase):
    def test_empty(self):
        self.assertEqual(total([]), 0)

    def test_numbers_and_input(self):
        values = [2, -5, 1.5]
        self.assertEqual(total(values), -1.5)
        self.assertEqual(values, [2, -5, 1.5])

    def test_iterator(self):
        self.assertEqual(total(iter([1, 2, 3])), 6)
